/// UTS #35 §4.7 flexible day-period rules for `en` (supplemental/dayPeriods.json).
/// `(key, at, from, before)` in minutes past local midnight; `at` is -1 for a
/// range rule, and `from`/`before` are -1 for an instant rule. `at` rules win.
pub const DAY_PERIOD_RULES: &[(&str, i32, i32, i32)] = &[
    ("afternoon1", -1, 720, 1080),
    ("evening1", -1, 1080, 1260),
    ("midnight", 0, -1, -1),
    ("morning1", -1, 0, 720),
    ("night1", -1, 1260, 1440),
    ("noon", 720, -1, -1),
];

