/// The `{1} … {0}` glue joining a date pattern to a time pattern.
pub const DATETIME_GLUE: [&str; 4] = ["{1}, {0}", "{1}, {0}", "{1}, {0}", "{1}, {0}"];
/// The `atTime` glue CLDR 42+ uses when a dateStyle/timeStyle pair is joined
/// (`"{1} 'at' {0}"` for full/long in `en`); ICU picks this over the plain
/// glue for dateStyle+timeStyle, which is why `timedatestyle-en.js` accepts
/// both spellings.
pub const DATETIME_GLUE_AT: [&str; 4] = ["{1} 'at' {0}", "{1} 'at' {0}", "{1}, {0}", "{1}, {0}"];

